/* Variété des débuts de partie : la naissance, la première sortie, l'école, la passion qui s'éveille
   et l'adolescence ne se racontent pas deux fois de la même façon. Chaque grand moment a plusieurs
   versions, choisies au hasard (déterministe) selon le pays, le foyer, le milieu et le caractère. */
(function(root){const L=root.Life,clamp=(x,a=0,b=100)=>Math.max(a,Math.min(b,x));
const base={year:L.year,create:L.create};
const hash=(...a)=>L.hash(a.join('|'));
const ch=(label,note,fx={})=>({label,note,fx});
const ctxOf=(s,p)=>{const c=L.country(s,p);return{s,p,c,tier:p.wealthTier??.5,urban:!!p.urban,poor:(p.wealthTier??.5)<.35||c.income<4500,rich:(p.wealthTier??.5)>.65&&c.income>9000,sibs:p.birth?.siblings??0,name:p.name}};
const choose=(s,p,key,list,ctx)=>{const ok=list.filter(v=>!v.when||v.when(ctx));const w=ok.map(v=>v.w??1),tot=w.reduce((a,b)=>a+b,0);let t=hash(s.seed,p.id,'variant',key)*tot;for(let i=0;i<ok.length;i++){t-=w[i];if(t<=0)return ok[i]}return ok[0]};

/* ── Naissance ── */
const births=[
{when:c=>c.rich,text:c=>`Vous naissez dans une clinique propre et calme de ${c.c.name}. La famille attendait cet enfant depuis longtemps : la chambre était prête avant vous.`,label:'Ouvrir les yeux'},
{when:c=>c.poor&&!c.urban,text:c=>`Vous naissez à la maison, dans un village de ${c.c.name}, avec l’aide d’une sage-femme du voisinage. L’eau chauffe depuis le matin. Dehors, quelqu’un guette le chemin.`,label:'Pousser un premier cri'},
{when:c=>c.poor&&c.urban,text:c=>`Vous naissez dans un quartier dense de ${c.c.name}, dans une petite pièce partagée par plusieurs générations. Le bruit de la rue ne s’arrête jamais, et personne ne s’en plaint.`,label:'Écouter la rue'},
{text:c=>`Une nuit d’orage éclate quand vous arrivez. Les lumières vacillent, tout le monde court. Vous pleurez plus fort que la pluie. Vous naissez en ${c.c.name}.`,label:'Défier l’orage'},
{when:c=>c.sibs>=3,text:c=>`Dans la maison, ${c.sibs} frères et sœurs aînés se disputent déjà pour savoir qui vous portera en premier. Vous naissez en ${c.c.name}, dans une famille bruyante.`,label:'Rejoindre la bande'},
{when:c=>c.sibs===0,text:c=>`Vous êtes le premier enfant du foyer, en ${c.c.name}. Deux adultes vous regardent comme s’ils découvraient le monde avec vous.`,label:'Découvrir ces visages'},
{text:c=>`Vous arrivez deux semaines plus tôt que prévu, au milieu d’un repas de famille, en ${c.c.name}. Tout le monde a laissé son assiette pour courir.`,label:'Faire une entrée remarquée'},
{when:c=>c.urban&&!c.poor,text:c=>`Vous naissez à l’aube dans un hôpital de ${c.c.name}. Par la fenêtre, la ville s’éveille : les premiers bus, les premières lumières.`,label:'Voir la ville s’éveiller'},
{when:c=>!c.urban,text:c=>`Vous naissez à la campagne, en ${c.c.name}, un jour de marché. Les voisins passent toute la journée à faire la fête avant même de vous avoir vu.`,label:'Rejoindre la fête'},
{text:c=>`Personne n’avait prévu votre arrivée à cette date, ni à cette heure. Mais en ${c.c.name}, tout le monde sait improviser. Vous naissez entouré·e de gens affairés.`,label:'Arriver à l’improviste'}];
/* ── Première sortie ── */
const nurseries=[
{title:'Premier jour hors de la maison',text:c=>c.poor?'Dans votre famille, on se relaie pour garder les petits : une voisine, une grande sœur, parfois les champs ou l’atelier. Aujourd’hui, vous découvrez un espace où d’autres enfants jouent.':'Aujourd’hui, vous découvrez un lieu où d’autres enfants jouent : crèche, maternelle ou petit groupe. Les adieux sont courts, les larmes un peu moins.'},
{title:'La cour des grands',text:c=>`Un matin, on vous habille plus soigneusement que d’habitude. ${c.sibs>0?'Votre grand frère ou votre grande sœur vous donne la main.':'Un adulte vous tient la main un peu plus fort que d’habitude.'} Devant vous, une cour pleine d’enfants qui courent dans tous les sens.`},
{title:'Un nouvel endroit, une nouvelle odeur',text:c=>`Ça sent le savon, la peinture, la soupe qui chauffe. Il y a des dessins collés partout et des enfants qui parlent trop vite. Vous vous accrochez à votre doudou.`},
{title:'On vous présente aux autres',text:c=>`Une personne souriante vous présente aux autres enfants : « Voici ${c.name} ». Quinze regards se tournent vers vous. Il faut décider quoi en faire.`}];
const nurseryChoices=[[ch('Courir vers les jouets','Relations +5 · curiosité +3',{skills:{social:5},trait:['curiosity',3]}),ch('Rester collé·e à un adulte','Liens familiaux +5 · prudence',{parents:5,stress:3}),ch('Observer sans rien dire','Savoirs +5 · calme',{skills:{academic:5},stress:-2})],[ch('Faire connaissance avec un·e voisin·e de banc','Amitié · relations +4',{skills:{social:4},friend:true}),ch('Dessiner dans un coin','Créativité +5',{skills:{creative:5}}),ch('Pleurer un bon coup, puis jouer','Épanouissement +3 · stress −2',{happy:3,stress:-2})]];
/* ── École ── */
const schools=[
{when:c=>c.poor&&!c.urban,title:'Une longue marche vers l’école',text:c=>`L’école est à plusieurs kilomètres, au bout d’un chemin de terre. Vous partez avec d’autres enfants du village, avant le lever du soleil. Une salle, un tableau noir, un maître pour des dizaines d’élèves.`,choices:[ch('Marcher avec le groupe','Relations +6 · énergie −3',{skills:{social:6},energy:-3,friend:true}),ch('Réviser à voix haute en chemin','Savoirs +8 · énergie −4',{skills:{academic:8},energy:-4}),ch('Observer les bêtes et les champs','Savoirs +4 · curiosité +4',{skills:{academic:4},trait:['curiosity',4]})]},
{when:c=>c.rich,title:'Une rentrée en uniforme',text:c=>`Une école soignée, une tenue neuve, un cartable qui brille. Les enseignants connaissent déjà votre nom. Autour de vous, des enfants qui se connaissent depuis la crèche.`,choices:[ch('Me présenter à tout le monde','Relations +7 · confiance',{skills:{social:7},friend:true}),ch('Plonger dans les livres de la classe','Savoirs +9',{skills:{academic:9}}),ch('Rester avec les amis de toujours','Épanouissement +5',{happy:5})]},
{title:'Le grand jour de la rentrée',text:c=>`Dans la cour, un groupe joue, une bibliothèque vous intrigue et un enfant reste à l’écart. Vous avez cinq minutes pour décider de qui vous allez devenir ce premier jour.`,choices:[ch('Entrer dans le jeu','Relations +7 · nouvelle amitié',{skills:{social:7},friend:true}),ch('Explorer les livres','Savoirs +9 · curiosité +3',{skills:{academic:9},trait:['curiosity',3]}),ch('Aller vers l’enfant isolé','Relations +5 · sens du collectif',{skills:{social:5},impact:2,friend:true})]},
{when:c=>c.sibs>0,title:'Dans les pas de l’aîné·e',text:c=>`Votre frère ou votre sœur vous guide dans les couloirs : « Là, c’est la cantine. Là, ne jamais se mettre. Là, c’est le bureau de la directrice. » Vous retenez tout, ou presque.`,choices:[ch('Suivre son conseil à la lettre','Liens +5 · prudence',{parents:5,stress:-2}),ch('Tout explorer seul·e','Curiosité +4 · savoirs +4',{skills:{academic:4},trait:['curiosity',4]}),ch('Me faire mon propre cercle','Relations +6',{skills:{social:6},friend:true})]},
{title:'Une langue qui n’est pas tout à fait la vôtre',text:c=>`À la maison, on parle d’une façon. À l’école, on parle d’une autre. Les premiers jours, vous comprenez un mot sur deux. Quelqu’un vous fait un grand sourire et un geste pour vous inviter à vous asseoir.`,choices:[ch('Imiter les autres pour apprendre vite','Savoirs +6 · relations +3',{skills:{academic:6,social:3}}),ch('Demander de l’aide à un enfant bilingue','Relations +6 · amitié',{skills:{social:6},friend:true}),ch('Rester silencieux·se en attendant de comprendre','Savoirs +4 · stress +3',{skills:{academic:4},stress:3})]},
{title:'Le premier bulletin',text:c=>`Quelques semaines après la rentrée, votre premier carnet de notes arrive à la maison. Chacun a son avis sur ce qu’il faut en penser : le sérieux, la joie, l’inquiétude.`,choices:[ch('Être fier·e de ce que j’ai fait','Épanouissement +5',{happy:5,skills:{academic:3}}),ch('Me promettre de faire mieux','Savoirs +6 · stress +3',{skills:{academic:6},stress:3}),ch('Montrer à tout le monde','Relations +4 · réputation +2',{skills:{social:4},reputation:2})]},
{when:c=>c.urban,title:'Une école au milieu de la ville',text:c=>`Une grande école entre deux immeubles, un préau bruyant, des centaines d’enfants. Des klaxons passent derrière le mur. Votre classe a une fenêtre qui donne sur un arbre.`,choices:[ch('Choisir la place près de la fenêtre','Créativité +6 · rêverie',{skills:{creative:6}}),ch('Me faire remarquer par une blague','Relations +6 · réputation +1',{skills:{social:6},reputation:1}),ch('Écouter attentivement','Savoirs +8',{skills:{academic:8}})]}];
/* ── Ce qu'on fait quand personne ne nous y oblige (10-12 ans) ── */
const talents=[
{title:'Ce que vous faites quand personne ne vous l’impose',text:c=>'Une activité peut devenir une passion. Vos dispositions ne sont pas des frontières.',choices:[ch('Inventer et bricoler','Technique +10',{skills:{technical:10}}),ch('Dessiner, écrire, créer','Créativité +10',{skills:{creative:10}}),ch('Organiser un club','Gestion +6 · relations +5',{skills:{management:6,social:5},network:3}),ch('M’entraîner au grand air','Santé +7 · énergie +5',{health:7,energy:5})]},
{title:'Un été qui laisse des traces',text:c=>'Pendant les vacances, vous avez eu une idée fixe : un projet à vous, un secret, une cabane, un journal. Elle vous a occupé·e tout l’été.',choices:[ch('Construire une cabane ou un abri','Technique +9 · énergie −3',{skills:{technical:9},energy:-3}),ch('Tenir un journal secret','Créativité +8 · calme',{skills:{creative:8},stress:-3}),ch('Monter une petite bande','Relations +7 · gestion +4',{skills:{social:7,management:4},friend:true}),ch('Courir, grimper, explorer','Santé +8 · curiosité +4',{health:8,trait:['curiosity',4]})]},
{title:'Une question qui ne vous lâche plus',text:c=>'Pourquoi le ciel est bleu ? Comment fonctionne ce moteur ? D’où vient cette histoire ? Une question vous a pris au piège et vous cherchez la réponse partout.',choices:[ch('Lire tout ce que je trouve','Savoirs +10',{skills:{academic:10}}),ch('Démonter pour comprendre','Technique +9',{skills:{technical:9}}),ch('Poser des questions aux adultes','Relations +6 · savoirs +4',{skills:{social:6,academic:4}}),ch('Inventer ma propre explication','Créativité +8',{skills:{creative:8}})]},
{when:c=>c.poor,title:'Apprendre un geste utile',text:c=>'Un voisin, un oncle, une tante vous apprend un geste de son métier : réparer, cuisiner, tresser, conduire un troupeau. Vous êtes fier·e de savoir faire quelque chose d’utile.',choices:[ch('Apprendre à réparer','Technique +10',{skills:{technical:10}}),ch('Apprendre à cuisiner pour la famille','Gestion +6 · liens +5',{skills:{management:6},parents:5}),ch('Suivre l’oncle sur le marché','Relations +7 · réseau +3',{skills:{social:7},network:3})]},
{title:'Un héros, une héroïne',text:c=>'Un·e sportif·ve, un·e chanteur·se, un·e scientifique, un·e personnage de livre : vous avez trouvé quelqu’un à qui vous voudriez ressembler.',choices:[ch('M’entraîner comme lui ou elle','Santé +8 · énergie +4',{health:8,energy:4}),ch('Chanter, jouer, dessiner comme lui ou elle','Créativité +10',{skills:{creative:10}}),ch('Lire tout sur lui ou elle','Savoirs +9',{skills:{academic:9}}),ch('En parler à tout le monde','Relations +6',{skills:{social:6}})]}];
/* ── Qui voulez-vous devenir ? (15-17 ans) ── */
const teens=[
{title:'Qui avez-vous envie de devenir ?',text:c=>'Les attentes des autres commencent à peser. Vous pouvez choisir une direction, et en changer plus tard.',choices:[ch('Viser des études exigeantes','Savoirs +10 · stress +8',{skills:{academic:10},stress:8}),ch('Développer une pratique créative','Créativité +10 · épanouissement +5',{skills:{creative:10},happy:5}),ch('Apprendre un métier concret','Technique +10 · gestion +3',{skills:{technical:10,management:3}}),ch('Renforcer mon cercle','Relations +9 · réseau +8',{skills:{social:9},network:8,friend:true})]},
{title:'Un soir où tout paraît possible',text:c=>'Il est tard. Vous êtes assis·e sur un toit, un muret ou un lit, avec cette impression soudaine que tout est encore ouvert. Une seule chose vous manque : savoir ce que vous voulez vraiment.',choices:[ch('Rêver grand, sans me restreindre','Épanouissement +8 · ambition +4',{happy:8,trait:['ambition',4]}),ch('Dresser une liste de ce que je sais faire','Gestion +6 · savoirs +4',{skills:{management:6,academic:4}}),ch('En parler à quelqu’un','Liens +6 · stress −4',{parents:4,friendbond:4,stress:-4}),ch('Dormir dessus','Énergie +6',{energy:6})]},
{when:c=>c.poor,title:'Les attentes de la famille et les vôtres',text:c=>'Les adultes autour de vous ont leur idée sur ce que vous devriez faire : gagner votre vie vite, aider à la maison, rester près. Vous avez la vôtre, plus floue.',choices:[ch('Chercher une voie qui contente tout le monde','Gestion +6 · liens +4',{skills:{management:6},parents:4}),ch('Défendre mon idée à moi','Réputation +3 · stress +6',{reputation:3,stress:6}),ch('Apprendre en cachette ce qui m’attire','Savoirs +6 · créativité +4',{skills:{academic:6,creative:4}}),ch('Suivre le chemin déjà tracé','Liens +8 · épanouissement −3',{parents:8,happy:-3})]},
{title:'Une journée d’orientation',text:c=>'Votre école organise une journée : des anciens élèves, des artisans, des étudiants, des entreprises. Vous passez de stand en stand, un peu étourdi·e.',choices:[ch('Poser mille questions','Savoirs +6 · réseau +4',{skills:{academic:6},network:4}),ch('Rester à l’écoute d’une seule personne','Réseau +6 · savoirs +4',{network:6,skills:{academic:4}}),ch('Essayer des démonstrations','Technique +6 · créativité +4',{skills:{technical:6,creative:4}}),ch('Repartir sans rien décider','Stress −2',{stress:-2})]}];
const KINDS={school:{list:schools,age:[5,8]},talent:{list:talents,age:[10,13]},teen:{list:teens,age:[15,18]}};
const category={school:'Enfance',talent:'Enfance',teen:'Adolescence'};
function eventFor(s,p,id){const ctx=ctxOf(s,p),v=choose(s,p,id,KINDS[id].list,ctx);return{id,title:v.title,text:v.text(ctx),choices:v.choices,category:category[id],required:true}}
function plan(s){const p=s.person;if(!p.alive||s.pending||p.age<4)return;s.queue??=[];const age=p.age+1;
  for(const[id,k]of Object.entries(KINDS)){if(age>=k.age[0]&&age<k.age[1]&&!p.events.includes(id)&&!s.queue.some(e=>e.id===id)&&(id!=='teen'||true)){
    s.queue.push(eventFor(s,p,id));return}}}
/* Naissance et première sortie : variantes. */
function birthVariant(s){const p=s.person,ctx=ctxOf(s,p),v=choose(s,p,'birth',births,ctx);
  const text=v.text(ctx)+` Votre foyer dispose de ${Math.round(p.householdIncome).toLocaleString('fr-FR')} UPA par an. ${p.parentSupport?`Le soutien matériel est ${p.parentSupport}.`:''}`.trim();
  return{id:'birth',title:'Une vie que personne n’a encore vécue.',text,choices:[ch(v.label,'Chaque année compte. La frise va commencer à avancer.',{})],category:'Naissance'}}
L.create=function(seed,code,year){const s=base.create(seed,code,year);if(s.pending?.id==='birth'){const b=birthVariant(s);s.pending={...s.pending,title:b.title,text:b.text,choices:b.choices}}return s};
L.year=function(s,withEvent=true){if(withEvent&&s.person?.alive&&!s.pending)plan(s);return base.year(s,withEvent)};
/* Première sortie : on remplace le texte et les choix de ms-nursery par une variante. */
const nurseryMs=L.milestones?.milestones?.find(m=>m.id==='ms-nursery');
if(nurseryMs){const pickN=(s,p)=>Math.floor(hash(s.seed,p.id,'nursery')*nurseries.length);nurseryMs.title=(s,p)=>nurseries[pickN(s,p)].title;nurseryMs.text=(s,p)=>nurseries[pickN(s,p)].text(ctxOf(s,p));
  nurseryMs.choices=(s,p)=>nurseryChoices[Math.floor(hash(s.seed,p.id,'nursery2')*nurseryChoices.length)]}
L.variants={births,nurseries,schools,talents,teens};
})(typeof window!=='undefined'?window:globalThis);
